import{_ as t,o as r,c as s,ag as e}from"./chunks/framework.D5hoimZQ.js";const A=JSON.parse('{"title":"科学日报 · 2026-11-03（AI · LSA 稀疏注意力 / RoboArchitect / SecPO / CRoS / 招聘链审计）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-11-03-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-11-03-ai.md"}'),n={name:"topics/ai-system-architecture/science-daily-2026-11-03-ai.md"};function i(c,o,g,a,l,d){return r(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="科学日报-·-2026-11-03-ai-·-lsa-稀疏注意力-roboarchitect-secpo-cros-招聘链审计" tabindex="-1">科学日报 · 2026-11-03（AI · LSA 稀疏注意力 / RoboArchitect / SecPO / CRoS / 招聘链审计） <a class="header-anchor" href="#科学日报-·-2026-11-03-ai-·-lsa-稀疏注意力-roboarchitect-secpo-cros-招聘链审计" aria-label="Permalink to &quot;科学日报 · 2026-11-03（AI · LSA 稀疏注意力 / RoboArchitect / SecPO / CRoS / 招聘链审计）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-03.md</code> — 第53期 ｜ AI 板块（5 篇，全部 arXiv cs.AI） 落盘说明：文件名带 <code>-ai</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-03-ai-·-1-5-lsa-潜在稀疏注意力——把超长上下文注意力做成次二次" tabindex="-1">科学日报 2026-11-03（AI · 1/5）：LSA 潜在稀疏注意力——把超长上下文注意力做成次二次 <a class="header-anchor" href="#科学日报-2026-11-03-ai-·-1-5-lsa-潜在稀疏注意力——把超长上下文注意力做成次二次" aria-label="Permalink to &quot;科学日报 2026-11-03（AI · 1/5）：LSA 潜在稀疏注意力——把超长上下文注意力做成次二次&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-03.md</code> ｜ arXiv: 2610.42147 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：智能体工作流走向<strong>长时程任务</strong>、依赖<strong>超长上下文</strong>，但 <strong>&gt;1M token</strong> 时全注意力代价不可承受；稀疏注意力的现有 indexer 要么<strong>仍是二次代价</strong>，要么<strong>超长尺度掉精度</strong>。</li><li>方法：<strong>LSA（Latent Sparse Attention）</strong>——把 key 在<strong>学习到的潜在空间分层聚类</strong>，query <strong>给簇的层级打分</strong>（而非逐 key 打分），使 prefill / decode / 训练在长上下文都更快；两个变体 <strong>D-LSA（蒸馏，可套预训练模型）</strong> 与 <strong>N-LSA（仅用下一 token 损失原生训练）</strong>。</li><li>结果（实测）：在 <strong>GLM-5.3-FLASH（QWEN-3.8-27B）</strong>、<strong>10M token</strong> 下，D-LSA 单层注意力相对原稀疏注意力（全注意力）**预填充 22.7×（72.4×）、解码 4.6×（42.5×）**且精度相当；N-LSA 在 <strong>128k token</strong> 下以 <strong>1.6× 单层训练加速</strong>追平全注意力精度。</li><li>洞察（对本库 <code>ai-system-architecture</code>）： <ol><li><strong>「先聚类再打分」＝把 O(N²) 换成对『层级』的 O(log/层) 打分</strong>——判据：当逐元素打分太贵时，先问<strong>能否先建一个可复用的层级结构</strong>（呼应母题「<strong>改路径优于加力度</strong>」）。</li><li><strong>「两种落地方案（蒸馏 / 原生）」</strong>——既给存量模型后装，也给新训练；判据：<strong>好方法的落地接口往往要同时覆盖『存量改』与『增量训』</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-03-ai-·-2-5-roboarchitect——自动设计机器人智能体的「外骨架」" tabindex="-1">科学日报 2026-11-03（AI · 2/5）：RoboArchitect——自动设计机器人智能体的「外骨架」 <a class="header-anchor" href="#科学日报-2026-11-03-ai-·-2-5-roboarchitect——自动设计机器人智能体的「外骨架」" aria-label="Permalink to &quot;科学日报 2026-11-03（AI · 2/5）：RoboArchitect——自动设计机器人智能体的「外骨架」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-03.md</code> ｜ arXiv: 2610.42141 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：<strong>冻结的机器人策略</strong>放进 <strong>agent harness（外骨架）<strong>会强很多（由控制代码决定何时查策略/调视觉工具/直驱机械臂），但 harness 历来</strong>手工搭、每个机器人/基准重设计</strong>。</li><li>方法：<strong>RoboArchitect</strong>——一个<strong>编码模型观察 rollout、诊断失败、迭代改写</strong>围绕冻结策略的 harness；优化用一批 episode、评估用<strong>留出场景与任务</strong>；harness 还能<strong>演化自己的持久记忆</strong>（如有效抓取深度）。</li><li>结果（实测）：<strong>不更新任何权重</strong>，多个基准/策略上平均成功率：未见场景 <strong>9.7%→43.3%（4.5×）</strong>、未见任务 <strong>12.7%→40.2%（3.2×）</strong>；离训练分布越远增益越大——<strong>包一层演化出的 harness 甚至常胜过微调版</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>intelligence-self-learning</code>）： <ol><li><strong>「把失败当设计信号，把 harness 当可优化的模型」</strong>——不碰权重，只改<strong>控制代码</strong>，就拿到数倍提升；判据：<strong>性能瓶颈在『外骨架』时，先优化外骨架而不是微调模型</strong>。</li><li><strong>「外骨架自带持久记忆」</strong>——把经验（抓取深度等）沉淀进 harness、跨 episode 复用，是<strong>免权重的经验累积</strong>通道。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-03-ai-·-3-5-secpo——给提示注入防护补上「原则化」的对抗训练" tabindex="-1">科学日报 2026-11-03（AI · 3/5）：SecPO——给提示注入防护补上「原则化」的对抗训练 <a class="header-anchor" href="#科学日报-2026-11-03-ai-·-3-5-secpo——给提示注入防护补上「原则化」的对抗训练" aria-label="Permalink to &quot;科学日报 2026-11-03（AI · 3/5）：SecPO——给提示注入防护补上「原则化」的对抗训练&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-03.md</code> ｜ arXiv: 2610.41998 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：<strong>提示注入</strong>（不可信数据操纵智能体）是 AI 智能体头号威胁；防护最佳的 <strong>Meta-SecAlign</strong> 在<strong>自适应攻击</strong>下 ASR 仍逼近 <strong>100%</strong>。根因之一：<strong>DPO 把模型锚在『未设防的参考模型』</strong>，而后者本身不安全。</li><li>方法：观察到<strong>理想化的「注入不变、保住效用」oracle 参考模型</strong>的训练输出分布其实<strong>可近似获取</strong> → 导出<strong>SecPO 损失</strong>；并用高效<strong>对抗训练（AT）<strong>合成</strong>强注入（best@240）</strong>。</li><li>结果（实测）：相比 Meta-SecAlign，AT 在三种 SOTA 自适应攻击下 ASR <strong>降 1.5–14.5×</strong>，SecPO 再<strong>额外降 2.4–4.6×</strong>；智能体流程中 <strong>SecPO + AT 的 Qwen3.6-27B</strong> 于 AttackerMovesSecond 下 AgentDojo <strong>ASR@800 仅 8.8%（对比 78.8%）</strong>，九项基准<strong>良性效用无明显下降</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>cybersecurity</code>）： <ol><li><strong>「锚点选错，训练再努力也白搭」</strong>——DPO 的锚是<strong>不安全</strong>的参考模型；判据：<strong>给安全类训练挑『参考分布』时，先确认锚点本身安全</strong>（呼应母题「<strong>否证性判据优于肯定性判据</strong>」）。</li><li><strong>「强对抗样本 &gt; 弱模拟攻击」</strong>——防护的强度上限由<strong>攻击的强度</strong>决定；判据：<strong>评估防护前，先问训练/评估用的攻击够不够强</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-03-ai-·-4-5-cros——用「打乱思路顺序」度量并奖励思维链的因果性" tabindex="-1">科学日报 2026-11-03（AI · 4/5）：CRoS——用「打乱思路顺序」度量并奖励思维链的因果性 <a class="header-anchor" href="#科学日报-2026-11-03-ai-·-4-5-cros——用「打乱思路顺序」度量并奖励思维链的因果性" aria-label="Permalink to &quot;科学日报 2026-11-03（AI · 4/5）：CRoS——用「打乱思路顺序」度量并奖励思维链的因果性&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-03.md</code> ｜ arXiv: 2610.42054 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：<strong>RLVR</strong> 只看最终答案对错，<strong>不保证思维链（CoT）对答案有因果贡献</strong>；现有因果度量靠<strong>删步/注入错误</strong>扰动 CoT，但<strong>扰动必然改变每步信息</strong> → 高分可能只反映「<strong>对信息变化的敏感</strong>」而非真因果，还会诱发<strong>更空洞的 CoT、更少探索与自我纠错</strong>。</li><li>方法：<strong>CRoS</strong>——<strong>只打乱推理步骤的顺序、不改内容</strong>，保留每步信息，从而<strong>隔离</strong>出真正的因果性并作为奖励。</li><li>结果（实测）：在 <strong>Reasoning Gym + Gemma-3-4B</strong> 上：域外准确率 <strong>46.8% vs 最强基线 43.8%</strong>、CoT-Pass@K（K=1..128）平均 <strong>43.4% vs 41.4%</strong>、提示承认分 <strong>34.0% vs 20.2%</strong>，全面领先。</li><li>洞察（对本库 <code>ai-system-architecture</code>）： <ol><li><strong>「扰动要只动你想动的那一维」</strong>——删步会连带改信息，打乱顺序则<strong>只动『顺序』</strong>；判据：<strong>做因果性/消融实验时，先让扰动『正交』于其它变量</strong>（避免混杂）。</li><li><strong>「奖励塑造的度量本身要被审」</strong>——错误的因果度量当奖励会<strong>训练出坏行为</strong>（空洞 CoT）；判据：<strong>先把度量本身的失效模式审清，再拿它当训练信号</strong>（同族：「<strong>指标高分 ≠ 学到机制</strong>」）。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-03-ai-·-5-5-全-ai-招聘链的偏见——模型选择本身会「刷掉」合格候选人" tabindex="-1">科学日报 2026-11-03（AI · 5/5）：全 AI 招聘链的偏见——模型选择本身会「刷掉」合格候选人 <a class="header-anchor" href="#科学日报-2026-11-03-ai-·-5-5-全-ai-招聘链的偏见——模型选择本身会「刷掉」合格候选人" aria-label="Permalink to &quot;科学日报 2026-11-03（AI · 5/5）：全 AI 招聘链的偏见——模型选择本身会「刷掉」合格候选人&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-03.md</code> ｜ arXiv: 2610.41866 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：求职者用 LLM 写求职信、雇主用 LLM 筛——在这条<strong>全 AI 链路</strong>里，<strong>所选模型是否独立于候选人资质影响录用结果</strong>？</li><li>方法：<strong>多模型审计框架</strong>——<strong>11 个写作智能体 × 9 个 API 评测智能体</strong>，覆盖 <strong>10 职位 × 每职位 50 候选人</strong>。</li><li>结果（实测，四点）：① 存在稳定**「生成偏好层级」<strong>：<strong>本地部署模型被系统性看低</strong>（无论许可），并叠加</strong>自我偏好偏差**；② 不同评测模型引入的<strong>偏倚程度差异大</strong>；③ 有<strong>可量化竞争后果</strong>：最不利配对下 25 名合格者约 <strong>1.8 名</strong>纯粹因<strong>模型错配</strong>被筛掉；④ 统一机制——偏好来自<strong>各模型对特定文体线索的倚重</strong>、以及评测方对这些线索（常<strong>一致地</strong>）的奖惩。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>career-observation</code>）： <ol><li><strong>「评测者的偏好层级 = 一种新的系统性偏差」</strong>——筛选结果会被<strong>写作/评测模型的配对</strong>左右；判据：<strong>AI 辅助筛选要审计『模型错配』这条隐蔽通道</strong>，而不只看显式特征。</li><li><strong>「自我偏好是自我强化的闭环」</strong>——评测方偏爱自家输出 → 同族模型互相提分；判据：<strong>评测与生成尽量异构/交叉</strong>（呼应库内「<strong>外部信号 &gt; 自评分</strong>」）。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/intelligence-self-learning/</code> ｜ <code>topics/cybersecurity/</code> ｜ <code>topics/career-observation/</code> ｜ 第53期 AI 板块</p></blockquote><p>关键词：科学日报第53期、LSA 潜在稀疏注意力、潜空间分层聚类、给簇层级打分、次二次注意力、超长上下文 10M token、D-LSA 蒸馏、N-LSA 原生、预填充22.7倍、解码4.6倍、RoboArchitect、自动设计 agent harness、外骨架、编码模型诊断失败、持久记忆、未见场景9.7%到43.3%、未见任务12.7%到40.2%、包一层 harness 胜过微调、SecPO、提示注入防护、注入不变 oracle 参考模型、DPO 锚点不安全、对抗训练 best@240、ASR 降1.5到14.5倍、AgentDojo ASR8.8%、CRoS、打乱 CoT 顺序、隔离信息变化混淆、CoT 因果性奖励、CoT-Pass@K、提示承认分34%、RLVR 只看答案对错、全 AI 招聘链审计、生成偏好层级、本地部署被看低、自我偏好偏差、模型错配刷掉合格者、文体线索、评测与生成异构交叉、改路径优于加力度、否证性判据优于肯定性判据、指标高分不等于学到机制、外部信号大于自评分</p><p>关联：<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/science-daily-2026-11-02-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-31-ai.md</code>、<code>topics/ai-system-architecture/liouville-goldbach-astra-claim.md</code>、<code>topics/intelligence-self-learning/index.md</code>、<code>topics/cybersecurity/index.md</code>、<code>topics/career-observation/index.md</code>、<code>topics/ai-brain/index.md</code>、<code>ScienceDaily/daily/2026-11-03.md</code></p>',26)])])}const u=t(n,[["render",i]]);export{A as __pageData,u as default};
